[InitializeOnLoad]public static class GridShiftV17PresentationChecks {
 static GridShiftV17PresentationChecks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("V17Presentation",false))new GameObject("V17 presentation checks").AddComponent<GridShiftV17PresentationRunner>();};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){if(!SessionState.GetBool("V17Presentation",false))return;DeliverySaveStore.OverridePath=Path.GetFullPath("Temp/V17Presentation-"+Guid.NewGuid().ToString("N")+"/slot.json");GridShiftCompany.SuppressIntro=true;GridShiftTutorial.Prefix="GS.V17.Presentation.";GridShiftTutorial.Skip();}
 public static void Batch(){EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");SessionState.SetBool("V17Presentation",true);EditorApplication.isPlaying=true;}
}
public sealed class GridShiftV17PresentationRunner:MonoBehaviour {
 readonly StringBuilder report=new StringBuilder();bool done;float timeout;
