 void Finish(bool success){if(done)return;done=true;SessionState.SetBool("V17Presentation",false);report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));Write();EditorApplication.Exit(success?0:1);}
 void Update(){if(!done&&timeout>0&&Time.realtimeSinceStartup>timeout){report.AppendLine("FAIL timeout");Finish(false);}}
