  float farther=orbit.distance;Action zoomIn=()=>UnityEngine.InputSystem.LowLevel.InputState.Change(Mouse.current.scroll,new Vector2(0,120));InputSystem.onAfterUpdate+=zoomIn;yield return null;InputSystem.onAfterUpdate-=zoomIn;yield return new WaitForSeconds(.1f);Check(orbit.distance<farther,"scroll up brings camera closer");
