  var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="V17 actual impact fixture";var bounds=van.GetComponent<BoxCollider>().bounds;wall.transform.position=bounds.center+van.transform.forward*(bounds.extents.z+.8f);wall.transform.rotation=van.transform.rotation;wall.transform.localScale=new Vector3(bounds.size.x+2,4,.2f);Physics.SyncTransforms();float before=van.Health.condition;van.SetInput(1,0,false);van.GetComponent<Rigidbody>().linearVelocity=van.transform.forward*6;yield return new WaitForSeconds(.5f);van.SetInput(0,0,true);Check(van.Health.condition<before-2,"actual rigidbody collision reduces mechanical condition");float after=van.Health.condition;yield return new WaitForSeconds(.5f);Check(van.Health.condition>after-.1f,"continuous contact does not repeat impact damage");Object.Destroy(wall);yield return null;
