 static IEnumerator PressInteract(){Application.runInBackground=true;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;if(Keyboard.current==null)InputSystem.AddDevice<Keyboard>();Action press=()=>UnityEngine.InputSystem.LowLevel.InputState.Change(Keyboard.current,new UnityEngine.InputSystem.LowLevel.KeyboardState(GridShiftControls.Binding(GSAction.Interact)));InputSystem.onAfterUpdate+=press;yield return null;InputSystem.onAfterUpdate-=press;yield return new WaitForSeconds(.05f);UnityEngine.InputSystem.LowLevel.InputState.Change(Keyboard.current,new UnityEngine.InputSystem.LowLevel.KeyboardState());yield return null;}
 static void Capture(string name,Camera view,int width,int height){var overlays=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var original=overlays.Select(c=>c.planeDistance).ToArray();var target=new RenderTexture(width,height,24);var previous=view.targetTexture;var active=RenderTexture.active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=view;c.planeDistance=.2f;}view.targetTexture=target;Canvas.ForceUpdateCanvases();view.Render();RenderTexture.active=target;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();Directory.CreateDirectory("Docs/Validacao17");File.WriteAllBytes("Docs/Validacao17/"+name+".png",image.EncodeToPNG());view.targetTexture=previous;RenderTexture.active=active;for(int i=0;i<overlays.Length;i++){overlays[i].renderMode=RenderMode.ScreenSpaceOverlay;overlays[i].worldCamera=null;overlays[i].planeDistance=original[i];}target.Release();Object.Destroy(target);Object.Destroy(image);}
